// Episode1Scene — top-down view of one Timedoor Academy branch, built from a
// real Tiled tilemap (data/episode1.tmj.json, generated by
// tools/generate-assets.mjs together with the tileset and props atlas):
//   'floor'     tile layer  — seamless 32px floor tiles
//   'walls'     tile layer  — wall/door/mat tiles; wall tiles carry a
//                             `collides` property so the physics comes from
//                             the map itself, not a separate rectangle list
//   'props'     object layer — furniture, each pointing at a frame in the
//                             'props' atlas
//   'collision' object layer — one rectangle per solid piece of furniture
//
// See data/stations.js for the landmark coordinates (reception desk, wall
// shelf, classroom).
//
// The scene drives the script from data/ep1Script.js. When the player walks
// close to the active target and presses E/Space, the corresponding overlay
// is shown (dialogue, inspection task, etc.). The scene is otherwise just a stage
// for the DOM-based overlay views.
import Phaser from 'phaser';
import { Player } from '../systems/player.js';
import { gameState } from '../state/gameState.js';
import { ep1Script } from '../data/ep1Script.js';
import { stations, NPC_POS, PLAYER_START, INTERACT_RADIUS } from '../data/stations.js';
import { overlay } from '../ui/overlay.js';
import { runDialogue } from '../ui/dialogue.js';
import { runInspect } from '../ui/inspect.js';
import { newDay, buildTask } from '../data/ep1Tasks.js';
import { debrief } from '../systems/inspectScoring.js';
import { saveGame } from '../state/storage.js';
import { runEp1Summary } from '../ui/summary.js';
import { crispText } from '../ui/crispText.js';

// Distance from each sprite's centre to its feet — Y-sort compares feet, the
// same edge the furniture hitboxes use.
const PLAYER_FEET = 30; // 72px frame, feet baseline at y=66
const MANAGER_FEET = 24; // 48px sprite

export class Episode1Scene extends Phaser.Scene {
  constructor() {
    super('Episode1Scene');
  }

  create() {
    // Reset state on (re)entry.
    gameState.episode1.report = [];
    gameState.episode1.tasks = {};
    gameState.episode1.notes = [];
    gameState.episode1.day = newDay();

    // World bounds match the visible room (no scrolling yet).
    this.physics.world.setBounds(0, 0, 640, 480);

    this.buildRoom();
    this.buildStations();
    this.buildNPC();
    this.buildPlayer();
    this.buildCollision();
    this.buildPrompt();

    this.cursors = this.input.keyboard.createCursorKeys();
    this.wasd = this.input.keyboard.addKeys('W,A,S,D');
    this.interactKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.E);
    this.interactKeyAlt = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

    // Drive the script.
    this.scriptIndex = 0;
    this.activeTarget = null;
    this.scriptDone = false;

    overlay.hide();
    this.runNextStep();
  }

  // ---------- World construction ----------

  buildRoom() {
    const map = this.make.tilemap({ key: 'episode1' });
    const tileset = map.addTilesetImage('timedoor_tiles', 'tiles');
    this.floorLayer = map.createLayer('floor', tileset, 0, 0).setDepth(0);
    this.wallsLayer = map.createLayer('walls', tileset, 0, 0).setDepth(1);
    this.wallsLayer.setCollisionByProperty({ collides: true });
    this.map = map;

    map.getObjectLayer('props').objects.forEach(o => {
      const frame = o.properties.find(p => p.name === 'frame').value;
      const sortY = o.properties.find(p => p.name === 'sortY');
      // Solid props share the player's 10 + feetY depth scale (see registerYSort)
      // so the player walks in front of or behind them correctly.
      this.add.image(o.x, o.y, 'props', frame).setOrigin(0).setDepth(sortY ? 10 + sortY.value : 2);
    });
  }

  buildStations() {
    this.arrowGfx = {};

    stations.forEach(st => {
      // The real furniture is already in the props layer. Just label it and give it a pulsing arrow.
      crispText(this, st.x, st.y + 26, st.label, {
        fontSize: '11px',
        fontFamily: '"Courier New", monospace',
        color: '#f4f1de',
        backgroundColor: '#0f0f1c',
        padding: { x: 4, y: 2 }
      }).setOrigin(0.5).setDepth(1000);

      // Pulsing arrow (hidden until this station is the active target).
      const arrow = this.add.image(st.x - 12, st.y - 40, 'arrow').setOrigin(0).setDepth(1000);
      arrow.setVisible(false);
      this.arrowGfx[st.id] = arrow;
    });
  }

  buildNPC() {
    // Manager NPC — single still frame, generated by tools/generate-assets.mjs.
    this.manager = this.add.image(NPC_POS.x, NPC_POS.y, 'manager').setOrigin(0.5);

    // Y-sorted (see registerYSort/applyYSort below) — depth is recalculated
    // every frame from its feet position instead of a fixed setDepth() call.
    this.registerYSort(this.manager, MANAGER_FEET);

    const managerLabel = crispText(this, NPC_POS.x, NPC_POS.y + 34, 'Manajer', {
      fontSize: '9px',
      fontFamily: '"Courier New", monospace',
      color: '#f4f1de',
      backgroundColor: '#0f0f1c',
      padding: { x: 4, y: 2 }
    }).setOrigin(0.5);
    // Y-sorts as if it were part of the manager sprite (see registerYSort's
    // followY), +1 so it draws just above the manager's own body depth.
    this.registerYSort(managerLabel, MANAGER_FEET + 1, this.manager);
  }

  buildPlayer() {
    this.player = new Player(this, PLAYER_START.x, PLAYER_START.y);

    // Y-sorted against the manager (and, later, any cut-out furniture piece
    // tall enough to stand in front of/behind) — see registerYSort/applyYSort.
    this.registerYSort(this.player.sprite, PLAYER_FEET);

    // Sprite is origin-centered and much taller than the old placeholder box,
    // so the "Kamu" label needs to float above the sprite's head — and follow
    // it, since (unlike the manager) the player actually walks around.
    this.playerLabel = crispText(this, PLAYER_START.x, PLAYER_START.y - 40, 'Kamu', {
      fontSize: '9px',
      fontFamily: '"Courier New", monospace',
      color: '#f4f1de',
      backgroundColor: '#0f0f1c',
      padding: { x: 4, y: 2 }
    }).setOrigin(0.5);
    // Y-sorts as if it were part of the player sprite (see registerYSort's
    // followY), +1 so it draws just above the player's own body depth.
    this.registerYSort(this.playerLabel, PLAYER_FEET + 1, this.player.sprite);
  }

  // ---------- Y-sort ----------
  //
  // Any sprite added here gets its depth recomputed every frame from its own
  // Y position (plus an optional per-object offset, e.g. to compensate for
  // an origin that isn't at the sprite's feet) — so two overlapping sprites
  // naturally draw whichever one is visually "lower" (closer to the camera
  // in a top-down room) on top. This is what makes the player walk in front
  // of the manager when below them and behind when above them.
  //
  // The room background/floor and other UI elements (prompts, arrows) are
  // NOT part of this system — they use fixed depths outside the Y-sort
  // range (background/floor at 0, furniture at 2, sortable actors + their
  // labels get depths in the 10-999 range via this list) so they're never
  // accidentally reordered relative to a walking character.
  //
  // A name label floats above its owner's head, so its own Y is always
  // "further up" than the character standing behind/in front of it — depth-
  // sorting the label by its OWN y would make every label draw as if it
  // belonged to whichever character is closest to the label's height, which
  // is wrong. Instead `followY` lets a label track a different object's Y
  // (its owner's) while keeping its own screen position — so "Manajer"
  // Y-sorts exactly as if it were part of the manager sprite, and likewise
  // for "Kamu" and the player.
  registerYSort(gameObject, feetOffset = 0, followY = null) {
    if (!this.ySortList) this.ySortList = [];
    this.ySortList.push({ obj: gameObject, feetOffset, followY });
  }

  applyYSort() {
    if (!this.ySortList) return;
    this.ySortList.forEach(({ obj, feetOffset, followY }) => {
      const y = followY ? followY.y : obj.y;
      obj.setDepth(10 + y + feetOffset);
    });
  }

  // Walls collide through the tile layer; furniture through the map's
  // 'collision' object layer (one invisible static body per rectangle).
  buildCollision() {
    this.collisionGroup = this.physics.add.staticGroup();

    const rects = this.map.getObjectLayer('collision').objects;
    rects.forEach(r => {
      const zone = this.add.zone(r.x + r.width / 2, r.y + r.height / 2, r.width, r.height);
      this.physics.add.existing(zone, true); // true = static body
      this.collisionGroup.add(zone);
    });

    this.physics.add.collider(this.player.sprite, this.collisionGroup);
    this.physics.add.collider(this.player.sprite, this.wallsLayer);

    // DEBUG ONLY — outline every collision shape in red. Toggle with
    // window.__debugCollision before starting Episode 1.
    if (window.__debugCollision) {
      const g = this.add.graphics().setDepth(50);
      g.lineStyle(1, 0xff0000, 1);
      rects.forEach(r => g.strokeRect(r.x, r.y, r.width, r.height));
      this.wallsLayer.renderDebug(g, { tileColor: null, collidingTileColor: new Phaser.Display.Color(255, 0, 0, 60) });
    }
  }

  buildPrompt() {
    this.prompt = crispText(this, 0, 0, '[E] Cek', {
      fontSize: '11px',
      fontFamily: '"Courier New", monospace',
      color: '#1a1a2e',
      backgroundColor: '#06d6a0',
      padding: { x: 6, y: 3 }
    }).setOrigin(0.5).setDepth(1000).setVisible(false);
  }

  // ---------- Script runner ----------

  runNextStep() {
    if (this.scriptDone) return;

    const step = ep1Script[this.scriptIndex];
    if (!step) {
      this.scriptDone = true;
      return;
    }

    switch (step.type) {
      case 'dialogue':
        this.runDialogueStep(step);
        break;
      case 'navigate':
        this.runNavigateStep(step);
        break;
      case 'inspect':
        this.runInspectStep(step);
        break;
      case 'summary':
        this.scriptIndex += 1;
        this.scriptDone = true;
        runEp1Summary(() => this.startEpisode2());
        break;
      default:
        this.scriptIndex += 1;
        this.runNextStep();
    }
  }

  runDialogueStep(step) {
    const text = typeof step.text === 'function' ? step.text(gameState.episode1.day) : step.text;
    runDialogue(step.speaker, text, () => {
      this.scriptIndex += 1;
      this.runNextStep();
    });
  }

  runNavigateStep(step) {
    this.activeTarget = step.target;
    this.refreshActiveArrow();
    runDialogue(
      'Petunjuk',
      `Jalan ke <strong>${step.label}</strong> dan tekan [E] untuk mengecek.`,
      () => { /* wait for player to walk there */ },
      { dismissable: false, hint: 'auto' }
    );
    this.scriptIndex += 1;
  }

  runInspectStep(step) {
    // Clean state: no active target while the task is open.
    this.activeTarget = null;
    this.refreshActiveArrow();
    this.prompt.setVisible(false);

    const task = buildTask(step.task, gameState.episode1.day);
    const finish = result => {
      gameState.episode1.tasks[task.id] = result;
      result.items.filter(i => i.action === 'report').forEach(i => {
        gameState.episode1.report.push({ area: task.title, item: i.name, reason: i.reason, urgent: i.urgent });
      });
      saveGame(gameState);
      // Manager reacts to how the task went before moving on.
      runDialogue('Manajer Cabang', debrief(result), () => {
        this.scriptIndex += 1;
        this.runNextStep();
      });
    };

    if (task.mode === 'closeup') {
      // Hands-on task: pause the room and switch to the table close-up scene.
      this.scene.pause();
      this.scene.launch(task.scene, { task, onDone: finish });
    } else {
      runInspect(task, finish);
    }
  }

  refreshActiveArrow() {
    Object.entries(this.arrowGfx).forEach(([id, arrow]) => {
      arrow.setVisible(id === this.activeTarget);
    });
  }

  // ---------- Loop ----------

  update() {
    if (this.player) {
      this.player.update(this.cursors, this.wasd);
      this.playerLabel.setPosition(this.player.sprite.x, this.player.sprite.y - 40);
    }

    this.applyYSort();

    // Proximity check vs. active target.
    if (this.activeTarget && !overlay.isVisible()) {
      const target = stations.find(s => s.id === this.activeTarget);
      const dist = Phaser.Math.Distance.Between(
        this.player.sprite.x, this.player.sprite.y,
        target.x, target.y
      );

      if (dist < INTERACT_RADIUS) {
        this.prompt.setPosition(this.player.sprite.x, this.player.sprite.y - 44);
        this.prompt.setVisible(true);

        if (Phaser.Input.Keyboard.JustDown(this.interactKey) ||
            Phaser.Input.Keyboard.JustDown(this.interactKeyAlt)) {
          // Consume the navigation step — run the next script step
          // (which the script author should have placed as an 'inspect').
          const next = ep1Script[this.scriptIndex];
          if (next && next.type === 'inspect') {
            this.runInspectStep(next);
          } else {
            // Defensive: if there's no checklist queued, just advance.
            this.scriptIndex += 1;
            this.runNextStep();
          }
        }
      } else {
        this.prompt.setVisible(false);
      }
    } else {
      this.prompt.setVisible(false);
    }

    // Arrow bob animation (only the visible one).
    const t = this.time.now / 200;
    Object.values(this.arrowGfx).forEach(a => {
      if (!a.visible) return;
      const baseY = stations.find(s => s.id === this.activeTarget).y - 40;
      a.y = baseY + Math.sin(t) * 4;
    });
  }

  // ---------- Scene transitions ----------

  startEpisode2() {
    overlay.hide();
    this.scene.start('Episode2Scene');
  }
}